sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float radius;
uniform float threshold;
uniform float intensity;
float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
float4 bright(float2 uv){float4 c=readInput(uv);float l=max(c.r,max(c.g,c.b));return c*smoothstep(threshold,threshold+.15,l);}
half4 main(float2 coord){float4 src=readInput((coord / size)),blur=float4(0.0);float weight=0.0;for(int j=1;j<=3;j++){float r=float(j)/3.0,w=exp(-r*r*2.0);for(int i=0;i<8;i++){float a=float(i)*.7853981634;blur+=bright((coord / size)+float2(cos(a),sin(a))*radius*r)*w;weight+=w;}}blur/=max(weight,1.0);float a=clamp(src.a+blur.a*intensity,0.0,1.0);return float4(min(src.rgb+blur.rgb*intensity,float3(a)),a);}
